# find nonzero coords per grid, derive block bbox properly
def bbox(P):
    arr=np.array(P); nz=(arr!=0)
    rows,cols=np.where(nz)
    return rows.min(),rows.max(),cols.min(),cols.max()
def f(P):
    r0,r1,c0,c1=bbox(P)
    b=P[r0:r1+1,c0:c1+1]; n=b.shape[0]
    return [[int(b[min(i,j)%n][min(i,j)%n]) for j in range(2*n)] for i in range(2*n)]
